        running0 += m0 ? xv.x : 0.0f;
        running1 += m1 ? xv.y : 0.0f;
        running2 += m2 ? xv.z : 0.0f;
        running3 += m3 ? xv.w : 0.0f;
        *reinterpret_cast<float4*>(out + offset) = make_float4(running0, running1, running2, running3);
    }
}

// Warp-shuffle kernel for innermost dimension (inner_size == 1), dim_size <= 32.
// Each warp handles one row using __shfl_up_sync for the inclusive prefix scan.
template <typename scalar_t>
__global__ void masked_cumsum_warp_kernel(
    const scalar_t* __restrict__ x,
    const bool*     __restrict__ mask,
    scalar_t*       __restrict__ out,
    int64_t outer_size,
    int64_t dim_size
) {
    int warp_id = threadIdx.x / 32;
    int lane = threadIdx.x % 32;
    int row = blockIdx.x * (blockDim.x / 32) + warp_id;
    if (row >= outer_size) return;

    const scalar_t* x_row    = x    + (int64_t)row * dim_size;
    const bool*     mask_row = mask + (int64_t)row * dim_size;
    scalar_t*       out_row  = out  + (int64_t)row * dim_size;

    scalar_t v = static_cast<scalar_t>(0);
    if (lane < dim_size) {
        v = mask_row[lane] ? x_row[lane] : static_cast<scalar_t>(0);
    }

    for (int offset = 1; offset < 32; offset <<= 1) {
        scalar_t tmp = __shfl_up_sync(0xffffffff, v, offset);
        if (lane >= offset) v += tmp;
    }

    if (lane < dim_size) {
        out_row[lane] = v;
    }
}

// Shared-memory kernel for innermost dimension (inner_size == 1), dim_size <= 1024.
template <typename scalar_t>
__global__ void masked_cumsum_innermost_kernel(
    const scalar_t* __restrict__ x,
    const bool*     __restrict__ mask,
    scalar_t*       __restrict__ out,
    int64_t dim_size
) {
    extern __shared__ char smem[];
    scalar_t* sdata = reinterpret_cast<scalar_t*>(smem);

    int row = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    const scalar_t* x_row    = x    + (int64_t)row * dim_size;
    const bool*     mask_row = mask + (int64_t)row * dim_size;
    scalar_t*       out_row  = out  + (int64_t)row * dim_size;

    scalar_t v = static_cast<scalar_t>(0);
    if (tid < dim_size) {
        v = mask_row[tid] ? x_row[tid] : static_cast<scalar_t>(0);
    }
    sdata[tid] = v;
    __syncthreads();

    for (int stride = 1; stride < block_size; stride <<= 1) {
        scalar_t tmp = static_cast<scalar_t>(0);
        if (tid >= stride && tid < dim_size) {
            tmp = sdata[tid - stride];
        }
        __syncthreads();
        if (tid >= stride && tid < dim_size) {
            sdata[tid] += tmp;
        }
        __syncthreads();
    }

    if (tid < dim_size) {
        out_row[tid] = sdata[tid];
    }
}

torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(mask.is_cuda(), "mask must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(mask.is_contiguous(), "mask must be contiguous");
    TORCH_CHECK(mask.scalar_type() == torch::kBool, "mask must be bool");
    TORCH_CHECK(x.sizes() == mask.sizes(), "x and mask must have the same shape");

    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    auto out = torch::empty_like(x);
    if (out.numel() == 0) return out;

    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= x.size(i);
    int64_t dim_size  = x.size(dim);
    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= x.size(i);

    if (x.scalar_type() == torch::kFloat32 && inner_size % 4 == 0) {
        uintptr_t x_ptr = reinterpret_cast<uintptr_t>(x.data_ptr<float>());
        uintptr_t m_ptr = reinterpret_cast<uintptr_t>(mask.data_ptr<bool>());
        uintptr_t o_ptr = reinterpret_cast<uintptr_t>(out.data_ptr<float>());
        if (((x_ptr | m_ptr | o_ptr) & 0xF) == 0) {
            int64_t total_groups = outer_size * (inner_size / 4);
            int threads = 256;
            int blocks = (int)((total_groups + threads - 1) / threads);
            masked_cumsum_generic_vec4_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
                x.data_ptr<float>(),
                mask.data_ptr<bool>(),
                out.data_ptr<float>(),
                outer_size,
                dim_size,
                inner_size
            );
            return out;
        }
    }

    AT_DISPATCH_FLOATING_TYPES(x.scalar_type(), "masked_cumsum_cuda", [&] {
        if (inner_size == 1 && dim_size <= 32) {
            int warps_per_block = 8;
            int threads = warps_per_block * 32;
            int blocks = (int)((outer_size + warps_per_block - 1) / warps_per_block);
            masked_cumsum_warp_kernel<scalar_t><<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
                x.data_ptr<scalar_t>(),
                mask.data_ptr<bool>(),
                out.data_ptr<scalar_t>(),
                outer_size,
                dim_size
            );
        } else if (inner_size == 1 && dim_size <= 1024) {
            int bs = 1;
            while (bs < dim_size) bs <<= 1;
            size_t smem_bytes = bs * sizeof(scalar_t);
            masked_cumsum_innermost_kernel<scalar_t><<<outer_size, bs, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
                x.data_ptr<scalar_t>(),
                mask.data_ptr<bool>(),
                out.data_ptr<scalar_t>(),
                dim_size
            );
        } else {
            int64_t total = outer_size * inner_size;
            int threads = 256;
            int blocks  = (int)((total + threads - 1) / threads);
            masked_cumsum_generic_kernel<scalar_t><<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
                x.data_ptr<scalar_t>(),
                mask.data_ptr<bool>(),
                out.data_ptr<scalar_t>(),
                outer_size,
                dim_size,
                inner_size
            );
        }
    });

    return out;
}
